/**
 * The server leg's specs — extracted from penguin's own route metadata, not hand-kept.
 *
 * `surface.json` is generated by `specs/extract.mjs` from:
 *   - `@Component({ contributes: { "HttpModule.routes": [{ id, prefix, auth }] } })` plus the
 *     `@Bind(id)` property and the `this.<prop> = <factory>(deps)` call that fills it: the
 *     platform's own mount table, plus each factory's `app.<method>("…")` calls joined onto
 *     the contribution's prefix;
 *   - `packages/web/src/api/endpoints.ts` + `packages/server/src/api/types.ts`: the method,
 *     path template and typed request DTO per client call, so a route with a body has its
 *     field names and types instead of a free-form blob — and a route whose registration
 *     computes its path (`base + "/move"`, which a literal scan cannot name) still appears
 *     when the client calls it.
 *
 * What stays here is policy the metadata cannot state: which routes the fuzzer must not
 * drive (they deploy code, drive a machine or a browser, reach the network, or start a
 * stream), and how a `:param` slot is filled.
 */
import fs from "node:fs";
import type { Choices } from "../../server/src/choices.js";
import { idValue, objectOf, type FieldSpec, type Pools, type Variant } from "../decode.js";

interface SurfaceRoute {
  group: string;
  auth: string;
  method: string;
  path: string;
}

interface SurfaceEndpoint {
  fn: string;
  method: string;
  path: string;
  params: string[];
  bodyType: string | null;
  fields: FieldSpec[];
}

interface Surface {
  routes: SurfaceRoute[];
  endpoints: SurfaceEndpoint[];
}

export interface HttpSpec {
  id: string;
  method: string;
  /** The template with `:param` slots, as the route declares it. */
  path: string;
  group: string;
  auth: string;
  fields: FieldSpec[];
  /** The request path, each `:param` filled from the spec (pool, literal, or a hostile draw). */
  url(variant: Variant, choices: Choices, text: string, pools: Pools): string;
  /** The request body, field by field, when the contract declares one. */
  body?: (
    variant: Variant,
    choices: Choices,
    text: string,
    pools: Pools,
  ) => Record<string, unknown>;
}

const surface = JSON.parse(
  fs.readFileSync(new URL("../surface.json", import.meta.url), "utf8"),
) as Surface;

/**
 * Routes the fuzzer must not drive. Each entry is a fact about the route, not a coverage
 * choice: it either holds a stream open that a fuzz call has no way to end, runs something on
 * the machine the harness owns, deploys code, or reaches the network. Driving one would be
 * either a false finding (the soft timeout, the outbound guard) or a real side effect outside
 * the disposable data root.
 */
const DANGER: readonly (readonly [RegExp, string])[] = [
  // A request that only returns when the client hangs up: one call is one infinite read.
  [/^\/api\/events$/, "event stream"],
  [/^\/api\/sessions\/[^/]+\/stream$/, "session event stream"],
  // Code the harness would run: HMR push, self-update, restart, rollback.
  [/^\/api\/hmr\b/, "deploys code (HMR push)"],
  [/^\/api\/version\/(update|update-check|restart|history\/rollback)\b/, "deploys or updates the harness"],
  // The machine and the harness's own browser.
  [/^\/api\/desktop\b/, "desktop machine control"],
  [/\/machines\b/, "machine control"],
  [/^\/server\//, "machine proxy"],
  [/^\/api\/builtin-browser\b/, "drives the harness's browser"],
  [/^\/api\/terminals\b/, "spawns a pty"],
  [/^\/api\/remote\//, "remote session control"],
  [/\/reveal$/, "opens the machine's file manager"],
  // The network: OAuth flows, model probes, the plugin registry, IM bridges, proxy probes.
  [/\/(model-oauth|modelscope-auth|platform-auth)\b/, "outbound OAuth flow"],
  [/\/models\/(balance|detect|detect-vision|list|test)$/, "probes a model API"],
  [/^\/api\/plugins\/registry\b/, "fetches the plugin registry"],
  [/\/messaging\//, "talks to an IM platform"],
  [/\/admin\/settings\/proxy-probe\b/, "probes a proxy"],
  [/\/config\/mcp-test$/, "spawns an MCP server"],
  [/\/plugins\/[^/]+\/(install|remove|update)$/, "network install"],
  // Filesystem imports and desk sessions.
  [/\/benchmarks\/(import|archive)$/, "filesystem import"],
];

function dangerOf(method: string, path: string): string | undefined {
  if (method === "ALL") return "catch-all route";
  if (path.includes("*")) return "catch-all route";
  // An org write hires, re-skins or wakes an employee, or posts into a channel that does: the
  // desk it reaches is a real session, not a row in the disposable data root.
  if (method !== "GET" && /\/organizations\b/.test(path)) return "org write opens desk sessions";
  for (const [pattern, reason] of DANGER) {
    if (pattern.test(path)) return reason;
  }
  return undefined;
}

/** `/api/projects/:projectId/agents` → the same string with every slot filled. */
function fill(
  path: string,
  variant: Variant,
  choices: Choices,
  text: string,
  pools: Pools,
): string {
  return path
    .split("/")
    .map((segment) => {
      if (!segment.startsWith(":")) return segment;
      // `/handbook/files/:path{.+}` — the braced part is Hono's own pattern for the slot.
      const name = segment.slice(1).replace(/\{[^}]*\}$/, "");
      const optional = name.endsWith("?");
      return encodeURIComponent(
        idValue(optional ? name.slice(0, -1) : name, choices, pools, variant === "bad"),
      );
    })
    .join("/");
}

export function httpSpecs(): HttpSpec[] {
  const fields = new Map<string, FieldSpec[]>();
  for (const endpoint of surface.endpoints) {
    if (endpoint.fields.length === 0) continue;
    fields.set(`${endpoint.method} ${endpoint.path}`, endpoint.fields);
  }

  const specs = new Map<string, HttpSpec>();
  const add = (method: string, path: string, group: string, auth: string): void => {
    if (dangerOf(method, path) !== undefined) return;
    const id = `${method} ${path}`;
    if (specs.has(id)) return;
    const declared = fields.get(id) ?? [];
    specs.set(id, {
      id,
      method,
      path,
      group,
      auth,
      fields: declared,
      url: (variant, choices, text, pools) => fill(path, variant, choices, text, pools),
      // No declared DTO → no structured body. The raw-body flag still sends the payload as
      // the body, which is how a body-parsing failure is reached on any route.
      ...(declared.length === 0
        ? {}
        : {
            body: (variant: Variant, choices: Choices, text: string, pools: Pools) =>
              objectOf(declared, variant, choices, text, pools),
          }),
    });
  };

  // Route metadata first: it names the group and carries the platform's own auth class.
  for (const route of surface.routes) add(route.method, route.path, route.group, route.auth);
  // Then the client's endpoints: the ones with a typed body attach their fields by id, and a
  // route the platform metadata missed still appears.
  for (const endpoint of surface.endpoints) add(endpoint.method, endpoint.path, endpoint.fn, "user");

  return [...specs.values()].sort((a, b) => a.id.localeCompare(b.id));
}
